CREATE OR REPLACE FUNCTION public._compra_solicitud_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_crear  boolean := false;
  v_origen text;
  v_quien  text;
begin
  -- IF anidados a propósito: en un INSERT no se toca OLD.
  if tg_op = 'INSERT' then
    -- Nace una solicitud: línea creada POR_COMPRAR, o personalizado nuevo.
    v_crear := NEW.estado = 'POR_COMPRAR' or (NEW.estado = 'ESPECIAL' and NEW.es_personalizado);
  else
    if OLD.estado is distinct from NEW.estado then
      if NEW.estado = 'POR_COMPRAR' then
        v_crear := true;

      -- La línea ya no se va a entregar: la compra deja de hacer falta.
      elsif NEW.estado in ('RECHAZADO','CAMBIADA','RETIRADA') then
        update compra_solicitud
           set estado = 'CANCELADA', cancelado_en = now(),
               cancelado_motivo = 'Línea ' || NEW.estado::text
         where pedido_linea_id = NEW.id and estado in ('SOLICITADA','COMPRADA');

      -- La línea se entregó (despacho normal, comprado directo o personalizado
      -- entregado): la compra queda cerrada.
      elsif NEW.estado in ('DESPACHADA','COMPRADO_DIRECTO') then
        update compra_solicitud
           set estado = 'RECIBIDA',
               recibido_en  = coalesce(recibido_en, now()),
               recibido_por = coalesce(recibido_por, NEW.modificado_por)
         where pedido_linea_id = NEW.id and estado in ('SOLICITADA','COMPRADA');
      end if;
    end if;
  end if;

  if v_crear and not exists (select 1 from compra_solicitud cs
                              where cs.pedido_linea_id = NEW.id
                                and cs.estado in ('SOLICITADA','COMPRADA')) then
    v_origen := case
      when NEW.es_personalizado then 'PERSONALIZADO'
      else coalesce(nullif(current_setting('roari.compra_origen', true), ''), 'ALMACEN')
    end;
    if v_origen not in ('VENDEDOR','ALMACEN','PERSONALIZADO') then
      v_origen := 'ALMACEN';
    end if;
    select coalesce(NEW.modificado_por, p.creado_por) into v_quien
      from pedido p where p.id = NEW.pedido_id;

    insert into compra_solicitud
      (pedido_linea_id, producto_id, descripcion, cantidad_base, origen, solicitado_por)
    values
      (NEW.id, NEW.producto_id,
       case when NEW.es_personalizado then NEW.descripcion end,
       NEW.cantidad_base, v_origen, v_quien);
  end if;

  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION public.comprar_directo(p_linea_id bigint, p_nota text, p_costo numeric DEFAULT NULL::numeric, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_linea pedido_linea%rowtype;
begin
  if not app_puede_inventariar() then
    raise exception 'Un cajero no puede marcar una línea como comprada directa.' using errcode = '42501';
  end if;
  select * into v_linea from pedido_linea where id = p_linea_id for update;
  if not found then raise exception 'Línea % no existe', p_linea_id; end if;
  if v_linea.estado in ('DESPACHADA', 'COMPRADO_DIRECTO') then raise exception 'La línea % ya está cerrada (%)', p_linea_id, v_linea.estado; end if;
  if p_nota is null or btrim(p_nota) = '' then raise exception 'La nota de compra directa es obligatoria'; end if;
  update pedido_linea set estado = 'COMPRADO_DIRECTO', compra_directa_nota = p_nota, compra_directa_costo = p_costo where id = p_linea_id;
  perform recalcular_estado_pedido(v_linea.pedido_id);
  return jsonb_build_object('linea_id', p_linea_id, 'estado', 'COMPRADO_DIRECTO');
end; $function$
CREATE OR REPLACE FUNCTION public.recibir_compra(p_solicitud_id bigint, p_ubicacion_id bigint DEFAULT NULL::bigint, p_cantidad_base numeric DEFAULT NULL::numeric, p_usuario text DEFAULT NULL::text, p_costo_total numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_s compra_solicitud%rowtype; v_l pedido_linea%rowtype; v_pedido pedido%rowtype;
  v_cant numeric; v_falta numeric; v_pres_base bigint; v_kardex_id bigint;
  v_actor text; v_estado text; v_linea_estado estado_linea;
  v_ubicacion bigint; v_costo_total numeric; v_costo_unit numeric;
begin
  if not app_puede_inventariar() then
    raise exception 'Un cajero no puede recibir compras.' using errcode = '42501';
  end if;
  if p_costo_total is not null and p_costo_total < 0 then
    raise exception 'El costo no puede ser negativo';
  end if;

  select * into v_s from compra_solicitud where id = p_solicitud_id for update;
  if not found then raise exception 'La solicitud de compra % no existe', p_solicitud_id; end if;
  if v_s.estado not in ('SOLICITADA','COMPRADA') then
    raise exception 'La solicitud % está % — no admite recepción', p_solicitud_id, v_s.estado;
  end if;

  select * into v_l from pedido_linea where id = v_s.pedido_linea_id for update;
  select * into v_pedido from pedido where id = v_l.pedido_id;
  if v_pedido.estado <> 'ABIERTO' then
    raise exception 'El pedido % está % — no admite recibir compras', v_l.pedido_id, v_pedido.estado;
  end if;

  v_falta := v_s.cantidad_base - v_s.cantidad_recibida;
  v_cant  := coalesce(p_cantidad_base, v_falta);
  if v_cant <= 0 then raise exception 'La cantidad recibida debe ser positiva'; end if;
  if v_cant > v_falta + 0.0001 then
    raise exception 'La cantidad recibida (%) excede lo que falta recibir (%)', v_cant, v_falta;
  end if;
  v_cant := least(v_cant, v_falta);

  v_actor := coalesce(p_usuario, auth.jwt() ->> 'email');
  v_linea_estado := v_l.estado;
  v_costo_total := coalesce(p_costo_total, v_s.costo_total);

  if not v_l.es_personalizado then
    -- a) ubicación: la indicada, o la de recepción de la sucursal de la línea.
    v_ubicacion := p_ubicacion_id;
    if v_ubicacion is null then
      select u.id into v_ubicacion from ubicacion u
       where u.sucursal_id = coalesce(v_l.sucursal_origen_id, 1) and u.es_recepcion
       limit 1;
      if v_ubicacion is null then
        raise exception 'La sucursal no tiene una ubicación de recepción configurada: indicá la ubicación donde entra la mercadería';
      end if;
    end if;

    select id into v_pres_base from presentacion
     where producto_id = v_l.producto_id and es_base = true limit 1;
    if v_pres_base is null then
      raise exception 'Producto % no tiene presentación base', v_l.producto_id;
    end if;

    -- b) costo por unidad base, sobre la cantidad total de la compra.
    v_costo_unit := case when v_costo_total is not null
                         then round(v_costo_total / v_s.cantidad_base, 4) end;

    select registrar_entrada(
      p_presentacion_id => v_pres_base,
      p_ubicacion_id    => v_ubicacion,
      p_cantidad_pres   => v_cant,
      p_referencia      => 'Compra para pedido ' || coalesce(v_pedido.numero, '#' || v_pedido.id)
                           || ' · línea ' || v_l.id,
      p_usuario         => v_actor,
      p_fecha           => (now() at time zone 'America/La_Paz')::date,   -- c)
      p_costo_unitario  => v_costo_unit
    ) into v_kardex_id;

    -- Con la primera recepción la línea vuelve a la cola de despacho (toma su
    -- turno por fecha del pedido, como cualquier otra).
    if v_l.estado = 'POR_COMPRAR' then
      update pedido_linea
         set estado = 'POR_DESPACHAR', modificado_por = v_actor, modificado_en = now()
       where id = v_l.id;
      v_linea_estado := 'POR_DESPACHAR';
    end if;
  end if;

  update compra_solicitud
     set cantidad_recibida = cantidad_recibida + v_cant,
         estado = case when cantidad_recibida + v_cant >= cantidad_base - 0.0001
                       then 'RECIBIDA' else 'COMPRADA' end,
         costo_total  = coalesce(p_costo_total, costo_total),
         comprado_por = coalesce(comprado_por, v_actor),
         comprado_en  = coalesce(comprado_en, now()),
         recibido_por = v_actor, recibido_en = now()
   where id = p_solicitud_id
   returning estado into v_estado;

  insert into pedido_evento (pedido_id, accion, motivo, usuario)
  values (v_l.pedido_id, 'COMPRA_RECIBIDA',
          'Recibido ' || v_cant::float8::text || ' de ' || v_s.cantidad_base::float8::text,
          v_actor);

  return jsonb_build_object(
    'solicitud_id', p_solicitud_id, 'estado', v_estado,
    'cantidad_recibida', v_s.cantidad_recibida + v_cant,
    'linea_id', v_l.id, 'linea_estado', v_linea_estado,
    'kardex_id', v_kardex_id, 'ubicacion_id', v_ubicacion);
end;
$function$
